import { useEffect } from 'react';

export const SITE_URL = 'https://speedpings.com';
export const SITE_NAME = 'Speed Pings';
export const DEFAULT_IMAGE = `${SITE_URL}/logo-wide.png`;

const setOrCreateMeta = (selector, attributes) => {
  let element = document.head.querySelector(selector);
  if (!element) {
    element = document.createElement('meta');
    document.head.appendChild(element);
  }
  Object.entries(attributes).forEach(([key, value]) => element.setAttribute(key, value));
};

const setCanonical = (url) => {
  let canonical = document.head.querySelector('link[rel="canonical"]');
  if (!canonical) {
    canonical = document.createElement('link');
    canonical.setAttribute('rel', 'canonical');
    document.head.appendChild(canonical);
  }
  canonical.setAttribute('href', url);
};

const removeManagedSchema = () => {
  document.head.querySelectorAll('script[data-speedpings-schema="true"]').forEach((node) => node.remove());
};

const addSchema = (schemas) => {
  removeManagedSchema();
  schemas.filter(Boolean).forEach((schema) => {
    const script = document.createElement('script');
    script.type = 'application/ld+json';
    script.setAttribute('data-speedpings-schema', 'true');
    script.textContent = JSON.stringify(schema);
    document.head.appendChild(script);
  });
};

export function absoluteUrl(path = '/') {
  const cleanPath = path === '/' ? '/' : `/${String(path).replace(/^\/+|\/+$/g, '')}`;
  return `${SITE_URL}${cleanPath}`;
}

export function useSEO({ title, description, path = '/', type = 'website', image = DEFAULT_IMAGE, schemas = [] }) {
  useEffect(() => {
    const url = absoluteUrl(path);
    document.title = title;

    setCanonical(url);
    setOrCreateMeta('meta[name="description"]', { name: 'description', content: description });
    setOrCreateMeta('meta[name="robots"]', { name: 'robots', content: 'index,follow,max-image-preview:large' });

    setOrCreateMeta('meta[property="og:title"]', { property: 'og:title', content: title });
    setOrCreateMeta('meta[property="og:description"]', { property: 'og:description', content: description });
    setOrCreateMeta('meta[property="og:type"]', { property: 'og:type', content: type });
    setOrCreateMeta('meta[property="og:url"]', { property: 'og:url', content: url });
    setOrCreateMeta('meta[property="og:site_name"]', { property: 'og:site_name', content: SITE_NAME });
    setOrCreateMeta('meta[property="og:image"]', { property: 'og:image', content: image });

    setOrCreateMeta('meta[name="twitter:card"]', { name: 'twitter:card', content: 'summary_large_image' });
    setOrCreateMeta('meta[name="twitter:title"]', { name: 'twitter:title', content: title });
    setOrCreateMeta('meta[name="twitter:description"]', { name: 'twitter:description', content: description });
    setOrCreateMeta('meta[name="twitter:image"]', { name: 'twitter:image', content: image });

    addSchema(schemas);
  }, [title, description, path, type, image, JSON.stringify(schemas)]);
}

export const organizationSchema = {
  '@context': 'https://schema.org',
  '@type': 'Organization',
  name: SITE_NAME,
  url: SITE_URL,
  logo: `${SITE_URL}/logo.png`,
  contactPoint: {
    '@type': 'ContactPoint',
    email: 'contact@speedpings.com',
    contactType: 'customer support'
  }
};

export const websiteSchema = {
  '@context': 'https://schema.org',
  '@type': 'WebSite',
  name: SITE_NAME,
  url: SITE_URL,
  inLanguage: 'en',
  potentialAction: {
    '@type': 'SearchAction',
    target: `${SITE_URL}/guides?search={search_term_string}`,
    'query-input': 'required name=search_term_string'
  }
};

export const appSchema = {
  '@context': 'https://schema.org',
  '@type': 'WebApplication',
  name: SITE_NAME,
  url: SITE_URL,
  applicationCategory: 'UtilityApplication',
  operatingSystem: 'Any',
  description: 'Free internet speed test tool to measure download speed, upload speed, ping, jitter, latency, WiFi speed, broadband speed, fiber speed, 4G and 5G performance.',
  offers: {
    '@type': 'Offer',
    price: '0',
    priceCurrency: 'USD'
  }
};

export const breadcrumbSchema = (items) => ({
  '@context': 'https://schema.org',
  '@type': 'BreadcrumbList',
  itemListElement: items.map((item, index) => ({
    '@type': 'ListItem',
    position: index + 1,
    name: item.name,
    item: absoluteUrl(item.path)
  }))
});

export const articleSchema = ({ title, description, path, image = DEFAULT_IMAGE }) => ({
  '@context': 'https://schema.org',
  '@type': 'Article',
  headline: title,
  description,
  image,
  mainEntityOfPage: absoluteUrl(path),
  author: { '@type': 'Organization', name: SITE_NAME },
  publisher: { '@type': 'Organization', name: SITE_NAME, logo: { '@type': 'ImageObject', url: `${SITE_URL}/logo.png` } }
});
